stijl:
@import url('https://fonts.googleapis.com/css2?family=Nunito+Sans:wght@300;400;600;700;800;900&display=swap');

:root {
  --nhl-blauw:  #003DA5;
  --nhl-paars:  #8C1D82;

  /* Exact thema-kleuren van de AI-Netwerk website */
  --t1: #1E3A8A;        /* AI & Leren */
  --t1-licht: #E8EFF8;
  --t2: #0F766E;        /* AI & Werken: teal-groen */
  --t2-licht: #E4F3EF;
  --t3: #E91E8C;        /* AI & Verantwoordelijkheid */
  --t3-licht: #FCE4F0;
  --t4: #7C3AED;        /* AI & Geletterdheid: paars */
  --t4-licht: #F2E8F9;
  --t5: #B45309;        /* AI & Werkveld: oranje-bruin */
  --t5-licht: #FAEEE9;
  --t6: #0E7490;        /* AI & Onderzoek: donker teal */
  --t6-licht: #E4F0F4;

  --grijs-licht: #F5F6F8;
  --grijs-mid:   #E0E4ED;
  --grijs-tekst: #4A5568;
  --body-tekst:  #1A2340;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Nunito Sans', 'Calibri', sans-serif;
  font-size: 15px;
  line-height: 1.72;
  color: var(--body-tekst);
  background: #fff;
}

/* COVER */
.cover {
  background: var(--nhl-blauw);
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
  position: relative;
  overflow: hidden;
}
.cover-geo {
  position: absolute; top: 0; right: 0;
  width: 420px; height: 420px; pointer-events: none;
}
.cover-geo svg { width: 100%; height: 100%; }
.cover-paars {
  position: absolute; top: 0; left: 0;
  width: 260px; height: 260px;
  background: var(--nhl-paars);
  clip-path: polygon(0 0, 100% 0, 0 100%);
}
.cover-dots {
  position: absolute; bottom: 60px; left: 60px;
  display: grid; grid-template-columns: repeat(4, 18px); gap: 10px;
}
.cover-dots span {
  width: 18px; height: 18px; border-radius: 50%;
  background: rgba(255,255,255,0.28); display: block;
}
.cover-dots span:nth-child(4),
.cover-dots span:nth-child(8) { opacity: 0; }
.cover-logo { padding: 40px 60px; position: relative; z-index: 10; }
.nhl-logo {
  display: inline-flex; flex-direction: column;
  border: 2.5px solid white; padding: 10px 14px; line-height: 1.1;
}
.nhl-logo-nhl { font-weight: 900; font-size: 22px; color: white; letter-spacing: 0.05em; }
.nhl-logo-stenden { font-weight: 400; font-size: 13px; color: white; letter-spacing: 0.2em; text-transform: uppercase; }
.cover-body {
  display: flex; flex-direction: column; justify-content: center;
  padding: 0 60px 0 300px; position: relative; z-index: 10;
}
.cover-supra { font-size: 11px; font-weight: 700; letter-spacing: 0.22em; text-transform: uppercase; color: rgba(255,255,255,0.55); margin-bottom: 14px; }
.cover-titel { font-size: 66px; font-weight: 900; color: white; line-height: 1.0; margin-bottom: 12px; }
.cover-titel-accent { color: #7BB8FF; }
.cover-subtitel { font-size: 19px; font-weight: 300; color: rgba(255,255,255,0.7); margin-bottom: 44px; line-height: 1.45; }
.cover-pills { display: flex; flex-wrap: wrap; gap: 8px; }
.cover-pill {
  background: rgba(255,255,255,0.11); border: 1px solid rgba(255,255,255,0.22);
  color: rgba(255,255,255,0.88); font-size: 12px; font-weight: 700;
  padding: 5px 13px; border-radius: 3px; letter-spacing: 0.03em;
}
.cover-footer {
  padding: 22px 60px; display: flex; justify-content: space-between; align-items: center;
  color: rgba(255,255,255,0.38); font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase;
  border-top: 1px solid rgba(255,255,255,0.1); position: relative; z-index: 10;
}
.cover-versie { background: var(--nhl-paars); color: white; padding: 4px 12px; border-radius: 2px; font-size: 11px; font-weight: 700; }

/* DOCUMENT */
.document { max-width: 920px; margin: 0 auto; padding: 80px 64px; }
.sectie-label { font-size: 10px; font-weight: 800; letter-spacing: 0.22em; text-transform: uppercase; color: var(--nhl-paars); margin-bottom: 8px; }
h1 { font-size: 38px; font-weight: 900; color: var(--nhl-blauw); line-height: 1.15; margin-bottom: 28px; }
h2 { font-size: 25px; font-weight: 800; color: var(--nhl-blauw); line-height: 1.25; margin-bottom: 14px; margin-top: 48px; }
h3 { font-size: 13px; font-weight: 800; color: var(--nhl-blauw); letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 12px; margin-top: 28px; }
p { margin-bottom: 16px; }
.lead { font-size: 19px; font-weight: 300; color: var(--nhl-blauw); line-height: 1.65; margin-bottom: 32px; }
.divider { height: 4px; background: linear-gradient(90deg, var(--nhl-paars) 0%, var(--nhl-blauw) 55%, transparent 100%); margin: 60px 0; border-radius: 2px; }

/* MANIFEST */
.manifest {
  background: linear-gradient(150deg, #002B75 0%, var(--nhl-blauw) 55%, #0A4BB8 100%);
  border-radius: 8px; padding: 52px 54px; margin: 44px 0; color: white;
  position: relative; overflow: hidden;
}
.manifest::before {
  content: ''; position: absolute; top: -70px; right: -70px; width: 260px; height: 260px;
  background: var(--nhl-paars); clip-path: polygon(100% 0, 100% 100%, 0 100%); opacity: 0.32;
}
.manifest-supra { font-size: 10px; font-weight: 800; letter-spacing: 0.24em; text-transform: uppercase; color: rgba(255,255,255,0.55); margin-bottom: 10px; }
.manifest h2 { color: white; margin-top: 0; font-size: 30px; margin-bottom: 26px; }
.manifest-punten { display: grid; grid-template-columns: 1fr 1fr; gap: 18px 26px; position: relative; z-index: 2; }
.manifest-punt { display: flex; gap: 13px; align-items: flex-start; }
.manifest-nr {
  flex-shrink: 0; width: 26px; height: 26px; border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,0.45); color: white;
  font-size: 12px; font-weight: 800; display: flex; align-items: center; justify-content: center; margin-top: 2px;
}
.manifest-punt h5 { font-size: 14px; font-weight: 800; color: white; margin-bottom: 4px; }
.manifest-punt p { font-size: 12.5px; color: rgba(255,255,255,0.75); line-height: 1.6; margin-bottom: 0; }
.manifest-band { margin: 34px 0 0; position: relative; z-index: 2; }
.manifest-band-label { font-size: 10px; font-weight: 800; letter-spacing: 0.2em; text-transform: uppercase; color: rgba(255,255,255,0.5); margin-bottom: 12px; }
.ambitie-rij { display: flex; align-items: center; gap: 12px; padding: 8px 0; border-top: 1px solid rgba(255,255,255,0.14); }
.ambitie-rij:last-child { border-bottom: 1px solid rgba(255,255,255,0.14); }
.ambitie-chip { flex-shrink: 0; width: 128px; text-align: center; font-size: 10px; font-weight: 800; letter-spacing: 0.04em; color: white; padding: 4px 8px; border-radius: 3px; }
.ambitie-tekst { font-size: 13.5px; font-weight: 700; color: white; font-style: italic; }
.manifest-belofte { margin-top: 30px; padding-top: 24px; border-top: 2px solid rgba(255,255,255,0.25); position: relative; z-index: 2; }
.manifest-belofte p { font-size: 19px; font-weight: 900; color: white; line-height: 1.4; margin-bottom: 0; }

/* BRONNEN PER KOERSLIJN */
.thema-bronnen { margin-top: 18px; padding: 13px 16px; background: var(--grijs-licht); border: 1px solid var(--grijs-mid); border-radius: 5px; }
.thema-bronnen h6 { font-size: 10px; font-weight: 800; letter-spacing: 0.14em; text-transform: uppercase; color: var(--grijs-tekst); margin-bottom: 7px; }
.thema-bronnen ul { list-style: none; margin: 0; padding: 0; }
.thema-bronnen li { font-size: 12px; color: var(--grijs-tekst); padding: 2.5px 0; padding-left: 16px; position: relative; }
.thema-bronnen li::before { content: '\2197'; position: absolute; left: 0; color: var(--nhl-paars); font-weight: 800; }
.thema-bronnen .tb-noot { font-size: 11px; color: #8A93A6; margin-top: 7px; margin-bottom: 0; font-style: italic; }

/* VIJFLAGENSTAPEL */
.lagen-stack { margin: 30px 0; }
.laag-rij { display: flex; align-items: center; gap: 14px; padding: 11px 16px; border: 1px solid var(--grijs-mid); border-radius: 5px; margin-bottom: 6px; background: white; }
.laag-nr { flex-shrink: 0; width: 30px; height: 30px; border-radius: 6px; color: white; font-size: 14px; font-weight: 800; display: flex; align-items: center; justify-content: center; }
.laag-naam { font-size: 13.5px; font-weight: 800; color: var(--nhl-blauw); min-width: 230px; }
.laag-oms { font-size: 12px; color: var(--grijs-tekst); flex: 1; line-height: 1.5; }
.laag-eig { flex-shrink: 0; font-size: 10.5px; font-weight: 700; color: var(--nhl-paars); background: #F7EBF5; border: 1px solid #E8CFE3; padding: 3px 9px; border-radius: 3px; }

/* WERKWIJZE STAPPEN */
.stappen { margin: 26px 0; }
.stap-rij { display: flex; gap: 14px; align-items: flex-start; margin-bottom: 12px; }
.stap-nr { flex-shrink: 0; width: 28px; height: 28px; border-radius: 50%; background: var(--nhl-blauw); color: white; font-size: 12.5px; font-weight: 800; display: flex; align-items: center; justify-content: center; margin-top: 2px; }
.stap-body { flex: 1; background: var(--grijs-licht); border: 1px solid var(--grijs-mid); border-radius: 5px; padding: 11px 15px; }
.stap-body h5 { font-size: 13px; font-weight: 800; color: var(--nhl-blauw); margin-bottom: 3px; }
.stap-body p { font-size: 12.5px; color: var(--grijs-tekst); line-height: 1.6; margin-bottom: 0; }

/* KEUZES-PAGINA (Ons vertrekpunt) */
.keuzes-box {
  background: linear-gradient(150deg, #002B75 0%, var(--nhl-blauw) 60%, #0A4BB8 100%);
  border-radius: 8px; padding: 46px 50px; margin: 36px 0; color: white;
  position: relative; overflow: hidden;
}
.keuzes-box::after { content:''; position:absolute; bottom:-70px; left:-70px; width:240px; height:240px; background:var(--nhl-paars); clip-path:polygon(0 0, 100% 100%, 0 100%); opacity:0.28; }
.keuzes-box .sectie-label { color: rgba(255,255,255,0.5); }
.keuzes-box h2 { color: white; font-size: 27px; margin: 6px 0 8px; }
.keuzes-intro { font-size: 15px; color: rgba(255,255,255,0.75); margin-bottom: 28px; }
.keuzes-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; position: relative; z-index: 2; }
.keuze-kaart { background: rgba(255,255,255,0.07); border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; padding: 20px 18px; }
.keuze-nr { font-size: 13px; font-weight: 900; color: #C9A8E8; letter-spacing: 0.12em; margin-bottom: 8px; }
.keuze-kaart h4 { font-size: 15px; font-weight: 800; color: white; margin-bottom: 8px; }
.keuze-kaart p { font-size: 12.5px; color: rgba(255,255,255,0.75); line-height: 1.65; margin-bottom: 0; }
.lagen-strip-kop { margin: 26px 0 12px; font-size: 13.5px; color: rgba(255,255,255,0.85); font-weight: 700; position: relative; z-index: 2; }
.lagen-strip { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; position: relative; z-index: 2; }
.laag-chip { background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.25); border-radius: 4px; padding: 7px 11px; font-size: 11.5px; color: white; }
.laag-chip b { color: #C9A8E8; margin-right: 5px; }
.laag-pijl { color: rgba(255,255,255,0.45); font-weight: 800; }
.keuzes-slot { margin: 22px 0 0; padding-top: 18px; border-top: 1px solid rgba(255,255,255,0.2); font-size: 16px; font-weight: 800; color: white; position: relative; z-index: 2; }

/* KOERSLIJN-SPREADS (v0.4 restyle) */
.kspread { position: relative; padding: 6px 2px 0; margin: 26px 0 10px; }
.kspread-ghost {
  position: absolute; top: -34px; right: -4px; font-size: 190px; font-weight: 900;
  color: var(--kl); opacity: 0.07; line-height: 1; letter-spacing: -0.05em; z-index: 0;
}
.kspread-kicker { font-size: 11px; font-weight: 800; letter-spacing: 0.22em; text-transform: uppercase; color: var(--kl); margin-bottom: 13px; position: relative; z-index: 2; }
.kspread-ambitie { font-size: 28px; font-weight: 900; color: var(--kl-donker); line-height: 1.28; max-width: 660px; position: relative; z-index: 2; }
.kspread-sub { font-size: 13px; color: #8A93A6; font-style: italic; margin-top: 9px; position: relative; z-index: 2; }
.kspread-lijn { width: 64px; height: 5px; background: var(--kl); margin: 19px 0 17px; border-radius: 2px; }
.kspread-lead { font-size: 14.5px; line-height: 1.75; color: var(--grijs-tekst); max-width: 710px; position: relative; z-index: 2; }
.kspread-keuzelabel { font-size: 11px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; color: var(--kl); margin: 22px 0 4px; }
.kspread-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 36px; }
.kspread-keuze { border-top: 2px solid var(--kl); padding: 11px 0 13px; font-size: 12.5px; line-height: 1.62; color: var(--grijs-tekst); }
.kspread-keuze strong { color: var(--kl-donker); }
.kspread-meet { display: flex; align-items: center; gap: 16px; margin-top: 12px; background: var(--kl-tint); border-left: 5px solid var(--kl); border-radius: 0 5px 5px 0; padding: 13px 18px; }
.kspread-meet-label { flex-shrink: 0; font-size: 17px; font-weight: 900; color: var(--kl); letter-spacing: 0.03em; }
.kspread-meet-tekst { font-size: 13px; color: var(--kl-donker); line-height: 1.55; font-weight: 600; }
.kspread-bron { margin-top: 11px; font-size: 11px; color: #98A1B3; }
.kspread-bron b { color: #6B7280; font-weight: 800; text-transform: uppercase; font-size: 9.5px; letter-spacing: 0.12em; margin-right: 6px; }

/* SPREAD-FAMILIE: inhoud, omgeving, betekenis, tijdlijn */
.sp-kicker { font-size: 11px; font-weight: 800; letter-spacing: 0.22em; text-transform: uppercase; color: var(--nhl-blauw); margin-bottom: 13px; }
.sp-lijn { width: 64px; height: 5px; background: var(--nhl-blauw); margin: 18px 0 16px; border-radius: 2px; }

.toc2-titel { font-size: 34px; font-weight: 900; color: var(--nhl-blauw); line-height: 1.15; }
.toc2-lead { font-size: 14px; line-height: 1.75; color: var(--grijs-tekst); max-width: 710px; margin-bottom: 8px; }
.toc2-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 44px; margin-top: 22px; }
.toc2-item { border-top: 1px solid var(--grijs-mid); padding: 10px 0; display: flex; gap: 14px; align-items: baseline; font-size: 13.5px; font-weight: 700; color: #1A2340; }
.toc2-nr { font-size: 11px; font-weight: 900; color: var(--nhl-paars); letter-spacing: 0.06em; }

.stat2-rij { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 36px; margin: 26px 0 10px; }
.stat2 { border-top: 2px solid var(--s); padding-top: 12px; }
.stat2-getal { font-size: 44px; font-weight: 900; color: var(--s); line-height: 1; letter-spacing: -0.02em; display: block; }
.stat2-label { font-size: 12.5px; color: var(--grijs-tekst); line-height: 1.5; margin-top: 8px; display: block; }
.stat2-bron { font-size: 10px; color: #98A1B3; margin-top: 6px; display: block; }

.omg2-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 36px; margin: 18px 0 6px; }
.omg2 { border-top: 2px solid var(--s); padding: 11px 0 13px; }
.omg2 h4 { font-size: 11px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; color: var(--s); margin-bottom: 7px; }
.omg2 p { font-size: 12.5px; line-height: 1.62; color: var(--grijs-tekst); margin-bottom: 0; }

.jou-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 0 34px; margin: 30px 0 10px; }
.jou { border-top: 2px solid var(--s); padding: 13px 0; }
.jou h4 { font-size: 11px; font-weight: 800; letter-spacing: 0.16em; text-transform: uppercase; color: var(--s); margin-bottom: 9px; }
.jou p { font-size: 13px; line-height: 1.68; color: var(--grijs-tekst); margin-bottom: 0; }

.golf-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 0 30px; margin-top: 22px; }
.golf { border-top: 2px solid var(--nhl-blauw); padding-top: 14px; }
.golf-jaar { font-size: 26px; font-weight: 900; color: var(--nhl-blauw); line-height: 1; }
.golf-fase { font-size: 11px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; color: var(--nhl-paars); margin: 5px 0 14px; }
.golf-item { padding: 7px 0; border-top: 1px solid var(--grijs-mid); }
.golf-thema { font-size: 9.5px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; display: block; margin-bottom: 2px; }
.golf-item p { font-size: 11.5px; line-height: 1.5; color: var(--grijs-tekst); margin: 0; }
.golf.eind .golf-item p { font-weight: 700; color: #1A2340; }

/* VOETVISUALS */
.voetvisual { margin-top: 30px; break-inside: avoid; page-break-inside: avoid; }
@media print {
  .vv-s { margin-top: 64px; }
  .vv-g { margin-top: 72px; }
  .vv-j { margin-top: 64px; }
  .vv-t { margin-top: 64px; }
}
.vv-kicker { font-size: 10px; font-weight: 800; letter-spacing: 0.22em; text-transform: uppercase; color: #98A1B3; margin-bottom: 14px; text-align: center; }
.vv-noot { font-size: 11px; color: #98A1B3; text-align: center; margin: 12px 0 0; font-style: italic; }

/* Route van elk experiment */
.route-strip { display: flex; align-items: center; justify-content: center; gap: 9px; flex-wrap: wrap; }
.route-stap { border: 1.5px solid var(--nhl-blauw); color: var(--nhl-blauw); border-radius: 4px; padding: 7px 14px; font-size: 11.5px; font-weight: 800; }
.route-stap.vol { background: var(--nhl-blauw); color: white; }
.route-pijl { color: #B9C2D0; font-weight: 800; }

/* Een programma, zeven lijnen */
.prog-visual { max-width: 640px; margin: 0 auto; }
.prog-top { background: var(--nhl-blauw); color: white; text-align: center; font-size: 13px; font-weight: 800; letter-spacing: 0.06em; padding: 10px; border-radius: 5px; }
.prog-verbind { display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; padding: 0 10px; }
.prog-verbind span { height: 12px; border-left: 2px solid #C9D2E0; margin-left: 50%; }
.prog-lijnen { display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; }
.prog-lijn { color: white; text-align: center; font-size: 9px; font-weight: 800; letter-spacing: 0.03em; padding: 9px 3px; border-radius: 4px; line-height: 1.35; }
.prog-basis { background: var(--nhl-paars); color: white; text-align: center; font-size: 11px; font-weight: 800; letter-spacing: 0.05em; padding: 8px; border-radius: 5px; margin-top: 8px; }

/* Convergentie: zes lijnen, een maatstaf */
.maatstaf-visual { text-align: center; }
.maatstaf-visual svg { width: 100%; max-width: 680px; height: auto; }

/* Horizonband tijdlijn */
.horizon-band { height: 9px; border-radius: 5px; background: linear-gradient(90deg, #1E3A8A 0%, #0F766E 20%, #E91E8C 40%, #7C3AED 60%, #B45309 80%, #0E7490 100%); }
.horizon-jaren { display: flex; justify-content: space-between; margin-top: 8px; padding: 0 2px; }
.horizon-jaren span { font-size: 11px; font-weight: 800; color: var(--nhl-blauw); }
.horizon-jaren span.eind { color: var(--nhl-paars); }

/* TOC */
.toc { border: 2px solid var(--nhl-blauw); border-radius: 4px; overflow: hidden; margin: 44px 0; display: grid; grid-template-columns: 1fr 1fr; }
.toc-header { grid-column: 1/-1; background: var(--nhl-blauw); color: white; padding: 13px 24px; font-size: 11px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; }
.toc-item { display: flex; align-items: flex-start; gap: 12px; padding: 10px 22px; border-bottom: 1px solid var(--grijs-mid); font-size: 13.5px; color: var(--nhl-blauw); font-weight: 600; }
.toc-item:nth-child(odd) { background: var(--grijs-licht); }
.toc-nr { font-size: 10px; font-weight: 800; color: var(--nhl-paars); min-width: 18px; padding-top: 2px; }

/* STATS */
.stat-rij { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; margin: 40px 0; border-radius: 6px; overflow: hidden; }
.stat-blok { background: var(--nhl-blauw); color: white; padding: 26px 20px; text-align: center; }
.stat-blok:nth-child(2) { background: var(--nhl-paars); }
.stat-blok:nth-child(3) { background: #1A3A7A; }
.stat-getal { display: block; font-size: 50px; font-weight: 900; line-height: 1; margin-bottom: 8px; }
.stat-label { display: block; font-size: 13px; color: rgba(255,255,255,0.85); line-height: 1.4; margin-bottom: 6px; }
.stat-bron { display: block; font-size: 10px; color: rgba(255,255,255,0.4); font-style: italic; }

/* OMGEVING */
.omgeving-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin: 28px 0; }
.omgeving-card { background: var(--grijs-licht); border-left: 4px solid var(--nhl-blauw); padding: 20px 22px; border-radius: 0 5px 5px 0; }
.omgeving-card.paars { border-left-color: var(--nhl-paars); }
.omgeving-card.groen { border-left-color: var(--t2); }
.omgeving-card.teal { border-left-color: var(--t6); }
.omgeving-card h4 { font-size: 11px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: var(--grijs-tekst); margin-bottom: 8px; }
.omgeving-card p { font-size: 13.5px; margin-bottom: 0; line-height: 1.6; }

/* EXTERN KADER */
.extern-kader { border: 1.5px solid #C7D2FE; background: #F0F4FF; border-radius: 5px; padding: 22px 26px; margin: 20px 0; }
.extern-tag { display: inline-block; background: var(--nhl-blauw); color: white; font-size: 9.5px; font-weight: 800; letter-spacing: 0.15em; text-transform: uppercase; padding: 2px 9px; border-radius: 2px; margin-bottom: 9px; }
.extern-kader h4 { font-size: 14.5px; font-weight: 700; color: var(--nhl-blauw); margin-bottom: 7px; margin-top: 0; text-transform: none; letter-spacing: normal; }
.extern-kader p { font-size: 13.5px; color: #2D3748; margin-bottom: 0; }

/* FUNDAMENT */
.fundament-box { background: var(--nhl-blauw); border-radius: 8px; padding: 44px 50px; margin: 36px 0; position: relative; overflow: hidden; }
.fundament-box::before { content: ''; position: absolute; top: -80px; right: -80px; width: 280px; height: 280px; background: var(--nhl-paars); clip-path: polygon(100% 0, 100% 100%, 0 100%); opacity: 0.3; }
.fundament-box .sectie-label { color: rgba(255,255,255,0.5); }
.fundament-box h2 { color: white; margin-top: 0; font-size: 27px; }
.fundament-intro { font-size: 15px; color: rgba(255,255,255,0.78); line-height: 1.7; margin-bottom: 32px; }
.pijlers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; position: relative; z-index: 2; }
.pijler { background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; padding: 20px 18px; }
.pijler-icon { font-size: 24px; margin-bottom: 10px; display: block; }
.pijler h4 { font-size: 14px; font-weight: 800; color: white; margin-bottom: 7px; }
.pijler p { font-size: 13px; color: rgba(255,255,255,0.7); line-height: 1.6; margin-bottom: 0; }

/* NETWERK SVG */
.netwerk-schema { margin: 44px 0; background: var(--grijs-licht); border-radius: 8px; padding: 28px; text-align: center; }
.netwerk-schema svg { width: 100%; max-width: 780px; }

/* KOERSLIJN */
.koerslijn { margin: 48px 0; border-radius: 8px; overflow: hidden; box-shadow: 0 2px 16px rgba(0,51,165,0.09); }
.koerslijn-header { padding: 26px 34px; display: flex; align-items: flex-start; gap: 18px; }
.koerslijn-nr { font-size: 50px; font-weight: 900; opacity: 0.16; line-height: 1; min-width: 60px; color: white; }
.koerslijn-header-txt h2 { color: white; margin: 0 0 6px; font-size: 23px; }
.koerslijn-vraag { font-size: 13px; font-style: italic; color: rgba(255,255,255,0.72); line-height: 1.5; }
.koerslijn-body { background: white; padding: 30px 34px; }
.koerslijn-body p { font-size: 14px; line-height: 1.75; }

/* KERNAMBITIE */
.kernambitie { margin: 0 0 22px; border-radius: 4px; overflow: hidden; }
.kernambitie-kop { display: flex; align-items: center; gap: 9px; padding: 9px 16px; background: var(--grijs-licht); border-bottom: 1px solid var(--grijs-mid); }
.kernambitie-kop-label { font-size: 10px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; }
.kernambitie-tekst { padding: 15px 18px; font-size: 17px; font-weight: 800; line-height: 1.45; color: white; }

/* AMBITIES */
.doel-label { font-size: 10px; font-weight: 800; letter-spacing: 0.2em; text-transform: uppercase; color: var(--grijs-tekst); margin-top: 22px; margin-bottom: 12px; display: block; }
.ambities { list-style: none; margin: 0 0 18px; }
.ambities li { display: flex; align-items: flex-start; gap: 11px; padding: 8px 0; border-bottom: 1px solid var(--grijs-mid); font-size: 13.5px; line-height: 1.6; }
.ambities li:last-child { border-bottom: none; }
.adot { width: 20px; height: 20px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 2px; font-size: 10px; color: white; font-weight: 800; }

/* INDICATOR */
.indicator { margin-top: 20px; padding: 13px 17px; border-radius: 4px; display: flex; align-items: flex-start; gap: 13px; }
.ind-icon { font-size: 18px; flex-shrink: 0; }
.ind-label { font-size: 10px; font-weight: 800; letter-spacing: 0.15em; text-transform: uppercase; margin-bottom: 3px; display: block; }

/* SANDBOX SECTIE */
.sandbox-box { background: linear-gradient(135deg, #0D2B52 0%, #1E3A8A 100%); border-radius: 8px; padding: 44px 50px; margin: 36px 0; position: relative; overflow: hidden; }
.sandbox-box::before { content: ''; position: absolute; bottom: -60px; right: -60px; width: 250px; height: 250px; background: var(--nhl-paars); clip-path: polygon(100% 0, 100% 100%, 0 100%); opacity: 0.25; }
.sandbox-box .sectie-label { color: rgba(255,255,255,0.5); }
.sandbox-box h2 { color: white; margin-top: 0; font-size: 27px; }
.sandbox-intro { font-size: 15px; color: rgba(255,255,255,0.8); line-height: 1.7; margin-bottom: 32px; }
.sandbox-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; position: relative; z-index: 2; margin-top: 28px; }
.sandbox-kaart { background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.18); border-radius: 6px; padding: 22px 20px; }
.sandbox-kaart h4 { font-size: 14px; font-weight: 800; color: white; margin-bottom: 8px; display: flex; align-items: center; gap: 8px; }
.sandbox-kaart p { font-size: 13px; color: rgba(255,255,255,0.72); line-height: 1.6; margin-bottom: 0; }
.sandbox-principes { list-style: none; margin: 24px 0 0; position: relative; z-index: 2; display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; }
.sandbox-principe { background: rgba(255,255,255,0.06); border-top: 3px solid var(--nhl-paars); border-radius: 0 0 5px 5px; padding: 14px 16px; }
.sandbox-principe h5 { color: white; font-size: 13px; font-weight: 800; margin-bottom: 5px; }
.sandbox-principe p { color: rgba(255,255,255,0.68); font-size: 12px; margin-bottom: 0; line-height: 1.55; }

/* GOVERNANCE */
.gov-lagen { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; border-radius: 6px; overflow: hidden; margin: 26px 0; }
.gov-laag { background: white; border-top: 4px solid var(--nhl-blauw); padding: 20px 16px; text-align: center; }
.gov-laag:nth-child(2) { border-top-color: var(--nhl-paars); }
.gov-laag:nth-child(3) { border-top-color: var(--t2); }
.gov-icon { font-size: 28px; margin-bottom: 9px; display: block; }
.gov-laag h4 { font-size: 13.5px; font-weight: 800; color: var(--nhl-blauw); margin-bottom: 6px; }
.gov-laag p { font-size: 12.5px; color: var(--grijs-tekst); margin-bottom: 0; line-height: 1.5; }

.gov-netwerk-diagram { margin: 32px 0; background: var(--grijs-licht); border-radius: 8px; padding: 28px; text-align: center; }
.gov-netwerk-diagram svg { width: 100%; max-width: 820px; }

.gov-tabel { width: 100%; border-collapse: collapse; margin: 26px 0; font-size: 13px; }
.gov-tabel th { background: var(--nhl-blauw); color: white; padding: 10px 15px; text-align: left; font-weight: 700; font-size: 11.5px; letter-spacing: 0.05em; }
.gov-tabel td { padding: 9px 15px; border-bottom: 1px solid var(--grijs-mid); vertical-align: top; line-height: 1.5; }
.gov-tabel tr:nth-child(even) td { background: var(--grijs-licht); }
.t-chip { display: inline-block; border-radius: 3px; padding: 2px 7px; color: white; font-size: 11px; font-weight: 700; }

/* TIJDLIJN */
.tijdlijn { margin: 36px 0; border-radius: 6px; overflow: hidden; }
.tl-header { display: grid; grid-template-columns: 105px 1fr 1fr 1fr; gap: 2px; margin-bottom: 2px; }
.tl-hcel { background: var(--nhl-blauw); color: rgba(255,255,255,0.82); font-size: 11px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; padding: 9px 13px; text-align: center; }
.tl-rij { display: grid; grid-template-columns: 105px 1fr 1fr 1fr; gap: 2px; margin-bottom: 2px; }
.tl-jaar { color: white; font-weight: 800; font-size: 12.5px; padding: 13px 8px; text-align: center; display: flex; align-items: center; justify-content: center; line-height: 1.3; }
.tl-cel { background: var(--grijs-licht); padding: 11px 13px; font-size: 12.5px; line-height: 1.5; color: var(--grijs-tekst); }
.tl-cel.doel { background: #EEF3FF; color: var(--nhl-blauw); font-weight: 600; }

/* GOVERNANCE AANVULLING */
.gov-aanvulling { background: #F8F9FF; border: 1px solid #C7D2FE; border-radius: 6px; padding: 28px 32px; margin: 24px 0; }
.gov-aanvulling h4 { font-size: 14px; font-weight: 800; color: var(--nhl-blauw); margin-bottom: 10px; margin-top: 0; text-transform: none; letter-spacing: normal; }
.gov-aanvulling p { font-size: 13.5px; line-height: 1.7; margin-bottom: 10px; }
.gov-aanvulling p:last-child { margin-bottom: 0; }

/* BRON NOOT */
.bron-noot { background: var(--grijs-licht); border-left: 3px solid var(--grijs-mid); padding: 13px 17px; font-size: 11.5px; color: var(--grijs-tekst); font-style: italic; line-height: 1.6; margin: 22px 0; border-radius: 0 4px 4px 0; }

/* BRONNEN */
.bronnen-blok { background: var(--grijs-licht); border-radius: 6px; padding: 30px 34px; margin: 48px 0 24px; }
.bronnen-blok h3 { margin-top: 0; }
.bronnen-lijst { list-style: none; }
.bronnen-lijst li { font-size: 12px; color: var(--grijs-tekst); padding: 5px 0; border-bottom: 1px solid var(--grijs-mid); line-height: 1.55; }
.bronnen-lijst li:last-child { border-bottom: none; }
.bchip { display: inline-block; background: var(--nhl-blauw); color: white; font-size: 9px; font-weight: 800; padding: 2px 6px; border-radius: 2px; margin-right: 7px; letter-spacing: 0.05em; vertical-align: middle; }

/* COLOFON */
.colofon { background: var(--nhl-blauw); border-radius: 6px; padding: 34px 38px; margin-top: 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 38px; }
.colofon h4 { font-size: 10px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; color: rgba(255,255,255,0.45); margin-bottom: 11px; }
.colofon p, .colofon li { font-size: 13px; color: rgba(255,255,255,0.8); line-height: 1.6; }
.colofon ul { list-style: none; }
.colofon ul li::before { content: ''; margin-right: 8px; color: var(--nhl-paars); }

/* Page breaks for print */
.page-break {
  page-break-before: always;
  break-before: page;
  height: 0;
  display: block;
}
@media screen {
  .page-break {
    height: 80px;
    border-top: 2px solid var(--grijs-mid);
    margin: 60px 0 40px;
  }
}

/* Paginering: samenhangende blokken blijven op een pagina */
.manifest, .toc, .leeswijzer, .keuzes-box, .keuze-kaart, .lagen-strip,
.extern-kader, .omgeving-card, .stat-rij, .bron-noot,
.fundament-box, .pijler,
.netwerk-schema, .lagen-stack, .laag-rij,
.kernambitie, .ambities li, .indicator, .thema-bronnen,
.kspread-keuze, .kspread-meet, .kspread-bron,
.stat2, .omg2, .jou, .golf-item, .toc2-item,
.sandbox-kaart, .sandbox-grid, .sandbox-principes, .sandbox-principe,
.gov-lagen, .gov-laag, .gov-netwerk-diagram, .gov-tabel, .gov-tabel tr,
.stap-rij, .voorstel-kader,
.tijdlijn, .tl-rij, .bronnen-blok li, .colofon {
  break-inside: avoid;
  page-break-inside: avoid;
}
h1, h2, h3, .sectie-label, .doel-label {
  break-after: avoid;
  page-break-after: avoid;
}
p { orphans: 3; widows: 3; }

@media print {
  .divider { display: none; }
  .manifest { padding: 36px 42px; margin: 24px 0; }
  .manifest h2 { font-size: 26px; margin-bottom: 18px; }
  .manifest-punten { gap: 13px 22px; }
  .manifest-punt p { font-size: 11.5px; line-height: 1.55; }
  .manifest-band { margin-top: 24px; }
  .ambitie-rij { padding: 6px 0; }
  .ambitie-tekst { font-size: 12.5px; }
  .manifest-belofte { margin-top: 20px; padding-top: 16px; }
  .manifest-belofte p { font-size: 17px; }

  /* Sandboxhoofdstuk op een pagina */
  .sandbox-box { padding: 28px 34px; margin: 16px 0; }
  .sandbox-box h2 { font-size: 22px; margin-bottom: 10px; }
  .sandbox-intro { font-size: 12.5px; margin-bottom: 14px; line-height: 1.55; }
  .sandbox-grid { gap: 12px; margin-top: 12px; }
  .sandbox-kaart { padding: 14px 15px; }
  .sandbox-kaart p { font-size: 11px; line-height: 1.5; }
  .sandbox-principes { margin-top: 14px; gap: 9px; }
  .sandbox-principe { padding: 10px 12px; }
  .sandbox-principe h5 { font-size: 11.5px; }
  .sandbox-principe p { font-size: 10.5px; line-height: 1.45; }

  /* Koerslijn op een pagina, inclusief bronnenvoet */
  .koerslijn { margin: 10px 0; box-shadow: none; }
  .koerslijn-header { padding: 18px 26px; }
  .koerslijn-body { padding: 20px 26px; }
  .koerslijn-body p { font-size: 12.5px; line-height: 1.6; }
  .kernambitie-tekst { font-size: 15px; padding: 12px 18px; }
  .ambities { margin-bottom: 12px; }
  .ambities li { font-size: 12px; line-height: 1.5; padding: 6px 0; }
  .indicator { padding: 12px 15px; }
  .indicator span { font-size: 12px !important; }
  .thema-bronnen { margin-top: 12px; padding: 10px 14px; }
  .thema-bronnen li { font-size: 11px; padding: 1.5px 0 1.5px 15px; }
  .thema-bronnen .tb-noot { font-size: 10px; margin-top: 5px; }

  /* Fundament en statistieken iets compacter */
  .fundament-box { padding: 30px 36px; }
  .pijler p { font-size: 11.5px; line-height: 1.55; }

  /* Omgevingsanalyse op een pagina */
  .stat-rij { margin: 20px 0; }
  .stat-blok { padding: 16px 14px; }
  .omgeving-grid { gap: 10px; margin: 16px 0; }
  .omgeving-card { padding: 13px 16px; }
  .omgeving-card p { font-size: 11px; line-height: 1.5; }
  .extern-kader { padding: 13px 18px; margin: 12px 0; }
  .extern-kader p { font-size: 11px; line-height: 1.5; }
  .extern-kader h4 { font-size: 13px; }
  .bron-noot { font-size: 9.5px; margin-top: 12px; }

  /* Vijflagenmodel en netwerkschema samen op een pagina */
  .lagen-stack { margin: 18px 0; }
  .laag-rij { padding: 8px 13px; margin-bottom: 5px; }
  .laag-naam { font-size: 12px; min-width: 190px; }
  .laag-oms { font-size: 10.5px; line-height: 1.45; }
  .laag-eig { font-size: 9.5px; }
  .netwerk-schema { margin: 14px 0; }
  .netwerk-schema svg { max-height: 400px; width: 100%; }

  /* Bronnen en colofon samen op de slotpagina */
  .bronnen-blok { padding: 18px 22px; }
  .bronnen-lijst li { font-size: 10.5px; padding: 3px 0; line-height: 1.5; }
  .colofon { padding: 22px 26px; margin-top: 14px; gap: 26px; }
  .colofon p, .colofon li { font-size: 10.5px; line-height: 1.5; }
}

/* LEESWIJZER */
.leeswijzer { background: var(--grijs-licht); border-left: 4px solid var(--nhl-paars); border-radius: 0 5px 5px 0; padding: 20px 26px; margin: 0 0 36px; }
.leeswijzer h5 { font-size: 10px; font-weight: 800; letter-spacing: 0.2em; text-transform: uppercase; color: var(--nhl-paars); margin-bottom: 9px; }
.leeswijzer p { font-size: 13px; color: var(--grijs-tekst); line-height: 1.7; margin-bottom: 9px; }
.leeswijzer p:last-child { margin-bottom: 0; }

/* VOORSTELKADER */
.voorstel-kader { border: 2px solid var(--nhl-paars); border-radius: 6px; overflow: hidden; margin: 28px 0; }
.voorstel-kader .vk-kop { background: var(--nhl-paars); color: white; padding: 9px 20px; font-size: 10px; font-weight: 800; letter-spacing: 0.18em; text-transform: uppercase; }
.voorstel-kader .vk-body { padding: 18px 22px; }
.voorstel-kader .vk-body p { font-size: 13.5px; line-height: 1.7; }
.voorstel-kader .vk-body p:last-child { margin-bottom: 0; }
